use std::collections::BTreeMap;

use anyhow::{Result, bail};
use serde_json::{Value, json};

use crate::api::client::{ApiError, SteelClient};
use crate::config::auth::Auth;
use crate::config::settings::ApiMode;
use crate::util::pairs::parse_pairs;

pub fn with_project(path: &str, project_id: Option<&str>) -> String {
    match project_id.map(str::trim).filter(|id| !id.is_empty()) {
        Some(project) => format!("{path}?projectId={}", urlencoding::encode(project)),
        None => path.to_string(),
    }
}

pub fn secret_path(id: &str, project_id: Option<&str>) -> String {
    with_project(&format!("/secrets/{}", urlencoding::encode(id)), project_id)
}

pub fn is_secret_id(value: &str) -> bool {
    let parts: Vec<&str> = value.split('-').collect();
    parts.len() == 5
        && parts.iter().zip([8, 4, 4, 4, 12]).all(|(part, len)| {
            part.len() == len && part.bytes().all(|byte| byte.is_ascii_hexdigit())
        })
}

pub fn parse_secret_ids(pairs: &[String]) -> Result<BTreeMap<String, String>> {
    let bindings = parse_pairs("--secret", "NAME=SECRET_ID", pairs)?;
    for (name, id) in &bindings {
        if !is_secret_id(id) {
            bail!(
                "--secret {name} wants a secret id, got {id:?}. Store the value with `steel secret create` first."
            );
        }
    }
    Ok(bindings)
}

#[derive(Debug, Default, Clone)]
pub struct CreateSecret {
    pub name: String,
    pub value: String,
    pub project_id: Option<String>,
}

impl CreateSecret {
    pub fn body(&self) -> Value {
        let mut body = json!({ "name": self.name, "value": self.value });
        if let Some(project) = &self.project_id {
            body["projectId"] = json!(project);
        }
        body
    }
}

#[derive(Debug, Default, Clone)]
pub struct UpdateSecret {
    pub name: Option<String>,
    pub value: Option<String>,
}

impl UpdateSecret {
    pub const fn is_empty(&self) -> bool {
        self.name.is_none() && self.value.is_none()
    }

    pub fn body(&self) -> Value {
        let mut body = json!({});
        if let Some(name) = &self.name {
            body["name"] = json!(name);
        }
        if let Some(value) = &self.value {
            body["value"] = json!(value);
        }
        body
    }
}

impl SteelClient {
    pub async fn list_secrets(
        &self,
        base_url: &str,
        mode: ApiMode,
        auth: &Auth,
        project_id: Option<&str>,
    ) -> Result<Value, ApiError> {
        self.request(
            base_url,
            mode,
            reqwest::Method::GET,
            &with_project("/secrets", project_id),
            None,
            auth,
        )
        .await
    }

    pub async fn create_secret(
        &self,
        base_url: &str,
        mode: ApiMode,
        auth: &Auth,
        request: &CreateSecret,
    ) -> Result<Value, ApiError> {
        self.request(
            base_url,
            mode,
            reqwest::Method::POST,
            "/secrets",
            Some(request.body()),
            auth,
        )
        .await
    }

    pub async fn get_secret(
        &self,
        base_url: &str,
        mode: ApiMode,
        auth: &Auth,
        id: &str,
        project_id: Option<&str>,
    ) -> Result<Value, ApiError> {
        self.request(
            base_url,
            mode,
            reqwest::Method::GET,
            &secret_path(id, project_id),
            None,
            auth,
        )
        .await
    }

    pub async fn update_secret(
        &self,
        base_url: &str,
        mode: ApiMode,
        auth: &Auth,
        id: &str,
        project_id: Option<&str>,
        request: &UpdateSecret,
    ) -> Result<Value, ApiError> {
        self.request(
            base_url,
            mode,
            reqwest::Method::PATCH,
            &secret_path(id, project_id),
            Some(request.body()),
            auth,
        )
        .await
    }

    pub async fn delete_secret(
        &self,
        base_url: &str,
        mode: ApiMode,
        auth: &Auth,
        id: &str,
        project_id: Option<&str>,
    ) -> Result<Value, ApiError> {
        self.request(
            base_url,
            mode,
            reqwest::Method::DELETE,
            &secret_path(id, project_id),
            None,
            auth,
        )
        .await
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const ID: &str = "2f1b6f2e-2c6f-4d9a-9c2a-8f4c1e0d7b31";

    #[test]
    fn paths_encode_ids_and_carry_the_project() {
        assert_eq!(secret_path("a b", None), "/secrets/a%20b");
        assert_eq!(
            secret_path(ID, Some("proj 1")),
            format!("/secrets/{ID}?projectId=proj%201")
        );
        assert_eq!(with_project("/secrets", Some("  ")), "/secrets");
    }

    #[test]
    fn secret_ids_are_uuids() {
        assert!(is_secret_id(ID));
        assert!(is_secret_id("00000000-0000-0000-0000-000000000000"));
        assert!(!is_secret_id("sk-live-abc"));
        assert!(!is_secret_id("2f1b6f2e-2c6f-4d9a-9c2a-8f4c1e0d7b3"));
        assert!(!is_secret_id("2f1b6f2e-2c6f-4d9a-9c2a-8f4c1e0d7b3g"));
    }

    #[test]
    fn secret_bindings_refuse_plain_values() {
        let bindings = parse_secret_ids(&[format!("TOKEN={ID}")]).unwrap();
        assert_eq!(bindings["TOKEN"], ID);
        let err = parse_secret_ids(&["TOKEN=sk-live-abc".into()]).unwrap_err();
        assert!(err.to_string().contains("steel secret create"));
    }

    #[test]
    fn bodies_only_carry_given_fields() {
        let create = CreateSecret {
            name: "TOKEN".into(),
            value: "abc".into(),
            project_id: None,
        };
        assert_eq!(create.body(), json!({ "name": "TOKEN", "value": "abc" }));
        let scoped = CreateSecret {
            project_id: Some("proj".into()),
            ..create
        };
        assert_eq!(
            scoped.body(),
            json!({ "name": "TOKEN", "value": "abc", "projectId": "proj" })
        );
        assert!(UpdateSecret::default().is_empty());
        let update = UpdateSecret {
            name: Some("API_TOKEN".into()),
            value: None,
        };
        assert_eq!(update.body(), json!({ "name": "API_TOKEN" }));
    }
}

//! Browser action handler: routes Clap subcommands to a persistent daemon
//! that holds the BrowserEngine (CDP connection + RefMap) alive between calls.

use std::collections::HashMap;

use anyhow::Result;
use clap::{Parser, Subcommand};

use crate::browser::daemon::client::DaemonClient;
use crate::browser::daemon::process;
use crate::browser::daemon::protocol::{
    DEFAULT_INACTIVITY_TIMEOUT_MS, DaemonCommand, DaemonCreateParams,
};
use crate::util::{api, output};

// ── Shared arg types ────────────────────────────────────────────────

#[derive(Parser)]
pub struct SelectorArg {
    /// Element selector or ref (e.g. @e1)
    pub selector: String,
}

// ── Top-level action enum ───────────────────────────────────────────

#[derive(Subcommand)]
pub enum ActionCommand {
    // --- Navigation ---
    /// Navigate to a URL
    #[command(aliases = ["open", "goto"])]
    Navigate(NavigateArgs),
    /// Navigate back in history
    Back,
    /// Navigate forward in history
    Forward,
    /// Reload the current page
    Reload,

    // --- Interactions ---
    /// Click an element
    Click(ClickArgs),
    /// Double-click an element
    #[command(name = "dblclick")]
    DblClick(SelectorArg),
    /// Fill an input field (clears existing value first)
    Fill(FillArgs),
    /// Type text into an element (appends to existing value)
    #[command(name = "type")]
    Type(TypeArgs),
    /// Press a keyboard key
    #[command(aliases = ["key"])]
    Press(PressArgs),
    /// Hover over an element
    Hover(SelectorArg),
    /// Focus an element
    Focus(SelectorArg),
    /// Check a checkbox or radio button
    Check(SelectorArg),
    /// Uncheck a checkbox
    Uncheck(SelectorArg),
    /// Select option(s) from a dropdown
    Select(SelectArgs),
    /// Clear an input field
    Clear(SelectorArg),
    /// Select all text in an input
    #[command(name = "selectall")]
    SelectAll(SelectorArg),
    /// Scroll the page or an element
    Scroll(ScrollArgs),
    /// Scroll an element into view
    #[command(name = "scrollintoview")]
    ScrollIntoView(SelectorArg),
    /// Set the value of an input element (without triggering events)
    #[command(name = "setvalue")]
    SetValue(SetValueArgs),

    // --- Observation ---
    /// Take an accessibility tree snapshot
    Snapshot(SnapshotArgs),
    /// Take a screenshot
    Screenshot(ScreenshotArgs),
    /// Evaluate JavaScript in the page
    Eval(EvalArgs),
    /// Find all elements matching a selector
    Find(SelectorArg),
    /// Get the page HTML content
    Content,

    // --- Get info ---
    /// Get information about elements or page
    Get {
        #[command(subcommand)]
        command: GetCommand,
    },

    // --- Check state ---
    /// Check element state
    Is {
        #[command(subcommand)]
        command: IsCommand,
    },

    // --- Waiting ---
    /// Wait for a condition (text, selector, URL, function, or timeout)
    Wait(WaitArgs),

    // --- Tabs ---
    /// Manage tabs
    Tab {
        #[command(subcommand)]
        command: TabCommand,
    },

    // --- Cookies ---
    /// Manage browser cookies
    Cookies {
        #[command(subcommand)]
        command: Option<CookiesCommand>,
    },

    // --- Storage ---
    /// Manage browser storage (localStorage/sessionStorage)
    Storage {
        #[command(subcommand)]
        command: StorageTypeCommand,
    },

    // --- Drag & drop ---
    /// Drag and drop from one element to another
    Drag(DragArgs),

    // --- File upload ---
    /// Upload files to a file input element
    Upload(UploadArgs),

    // --- Visual ---
    /// Visually highlight an element
    Highlight(SelectorArg),

    // --- Browser settings ---
    /// Configure browser settings (viewport, geolocation, etc.)
    Set {
        #[command(subcommand)]
        command: SetCommand,
    },

    // --- Window ---
    /// Bring the browser window to the foreground
    #[command(name = "bringtofront")]
    BringToFront,

    // --- Diff ---
    /// Compare snapshots or screenshots
    Diff {
        #[command(subcommand)]
        command: DiffCommand,
    },

    // --- Session ---
    /// Close the browser session
    #[command(aliases = ["quit", "exit"])]
    Close,
}

impl ActionCommand {
    pub const fn telemetry_name(&self) -> &'static str {
        match self {
            Self::Navigate(_) => "navigate",
            Self::Back => "back",
            Self::Forward => "forward",
            Self::Reload => "reload",
            Self::Click(_) => "click",
            Self::DblClick(_) => "dblclick",
            Self::Fill(_) => "fill",
            Self::Type(_) => "type",
            Self::Press(_) => "press",
            Self::Hover(_) => "hover",
            Self::Focus(_) => "focus",
            Self::Check(_) => "check",
            Self::Uncheck(_) => "uncheck",
            Self::Select(_) => "select",
            Self::Clear(_) => "clear",
            Self::SelectAll(_) => "selectall",
            Self::Scroll(_) => "scroll",
            Self::ScrollIntoView(_) => "scrollintoview",
            Self::SetValue(_) => "setvalue",
            Self::Snapshot(_) => "snapshot",
            Self::Screenshot(_) => "screenshot",
            Self::Eval(_) => "eval",
            Self::Find(_) => "find",
            Self::Content => "content",
            Self::Get { .. } => "get",
            Self::Is { .. } => "is",
            Self::Wait(_) => "wait",
            Self::Tab { .. } => "tab",
            Self::Cookies { .. } => "cookies",
            Self::Storage { .. } => "storage",
            Self::Drag(_) => "drag",
            Self::Upload(_) => "upload",
            Self::Highlight(_) => "highlight",
            Self::Set { .. } => "set",
            Self::BringToFront => "bringtofront",
            Self::Diff { .. } => "diff",
            Self::Close => "close",
        }
    }
}

// ── Get subcommands ─────────────────────────────────────────────────

#[derive(Subcommand)]
pub enum GetCommand {
    /// Get element text content
    Text(SelectorArg),
    /// Get element inner HTML
    Html(SelectorArg),
    /// Get input/textarea value
    Value(SelectorArg),
    /// Get element attribute value
    Attr(GetAttrArgs),
    /// Get current page URL
    Url,
    /// Get current page title
    Title,
    /// Count matching elements
    Count(SelectorArg),
    /// Get element bounding box
    #[command(name = "box")]
    Box(SelectorArg),
    /// Get element CSS styles
    Styles(StylesArgs),
}

// ── Is subcommands ──────────────────────────────────────────────────

#[derive(Subcommand)]
pub enum IsCommand {
    /// Check if element is visible
    Visible(SelectorArg),
    /// Check if element is enabled
    Enabled(SelectorArg),
    /// Check if element is checked
    Checked(SelectorArg),
}

// ── Tab subcommands ─────────────────────────────────────────────────

#[derive(Subcommand)]
pub enum TabCommand {
    /// List open tabs
    List,
    /// Open a new tab
    New(TabNewArgs),
    /// Switch to a tab by index
    Switch(TabSwitchArgs),
    /// Close a tab (active tab if no index given)
    Close(TabCloseArgs),
}

// ── Cookies subcommands ──────────────────────────────────────────────

#[derive(Subcommand)]
pub enum CookiesCommand {
    /// Set a cookie
    Set(CookiesSetArgs),
    /// Clear all cookies
    Clear,
}

// ── Storage subcommands ─────────────────────────────────────────────

#[derive(Subcommand)]
pub enum StorageTypeCommand {
    /// Manage localStorage
    Local(StorageSubArgs),
    /// Manage sessionStorage
    Session(StorageSubArgs),
}

#[derive(Parser)]
#[command(args_conflicts_with_subcommands = true)]
pub struct StorageSubArgs {
    /// Key to get (returns all if omitted)
    pub key: Option<String>,

    #[command(subcommand)]
    pub command: Option<StorageActionCommand>,
}

#[derive(Subcommand)]
pub enum StorageActionCommand {
    /// Set a storage value
    Set(StorageSetArgs),
    /// Clear all values
    Clear,
}

// ── Set subcommands ─────────────────────────────────────────────────

#[derive(Subcommand)]
pub enum SetCommand {
    /// Set viewport size
    Viewport(SetViewportArgs),
    /// Set geolocation
    #[command(aliases = ["geolocation"])]
    Geo(SetGeoArgs),
    /// Toggle offline mode
    Offline(SetOfflineArgs),
    /// Set extra HTTP headers (JSON string)
    Headers(SetHeadersArgs),
    /// Set browser user agent string
    #[command(name = "useragent", aliases = ["ua"])]
    UserAgent(SetUserAgentArgs),
}

// ── Diff subcommands ────────────────────────────────────────────────

#[derive(Subcommand)]
pub enum DiffCommand {
    /// Compare current snapshot against a baseline
    Snapshot(DiffSnapshotArgs),
    /// Compare current screenshot against a baseline image
    Screenshot(DiffScreenshotArgs),
}

#[derive(Parser)]
pub struct DiffSnapshotArgs {
    /// Baseline snapshot text or file path
    #[arg(short, long)]
    pub baseline: Option<String>,
    /// Restrict snapshot to a subtree
    #[arg(short, long)]
    pub selector: Option<String>,
    /// Use compact output format
    #[arg(short, long)]
    pub compact: bool,
    /// Maximum nesting depth
    #[arg(short = 'd', long, alias = "depth")]
    pub max_depth: Option<usize>,
}

#[derive(Parser)]
pub struct DiffScreenshotArgs {
    /// Baseline image file path (required)
    #[arg(short, long)]
    pub baseline: String,
    /// Color difference threshold (0.0–1.0)
    #[arg(short, long)]
    pub threshold: Option<f64>,
    /// Save diff image to this path
    #[arg(short, long)]
    pub output: Option<String>,
    /// Restrict screenshot to an element
    #[arg(short, long)]
    pub selector: Option<String>,
    /// Capture the full scrollable page
    #[arg(long, alias = "full")]
    pub full_page: bool,
}

// ── Arg structs ─────────────────────────────────────────────────────

