#!/usr/bin/env node

// @steel-dev/cli postinstall — installs the native Steel binary via cargo-dist.
// This script runs automatically after `npm install -g @steel-dev/cli`.

import { execSync } from "node:child_process";
import { existsSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const BINARY_DIR = join(homedir(), ".steel", "bin");
const BINARY_PATH = join(BINARY_DIR, "steel");
const INSTALLER_URL =
  "https://github.com/steel-dev/cli/releases/latest/download/steel-cli-installer.sh";

function main() {
  // Skip in CI unless explicitly requested
  if (process.env.CI && !process.env.STEEL_FORCE_INSTALL) {
    console.log("[steel] Skipping native binary install in CI.");
    console.log(
      "[steel] Set STEEL_FORCE_INSTALL=1 to override, or use: curl -sSf https://setup.steel.dev | sh"
    );
    return;
  }

  if (existsSync(BINARY_PATH)) {
    console.log(`[steel] Native binary already installed at ${BINARY_PATH}`);
    console.log(
      "[steel] The npm package is not needed. You can remove it with:"
    );
    console.log("[steel]   npm uninstall -g @steel-dev/cli");
    return;
  }

  console.log("[steel] Installing Steel CLI native binary...");
  console.log("");

  // Check for curl
  try {
    execSync("command -v curl", { stdio: "ignore" });
  } catch {
    console.error("[steel] Error: curl is required but not found.");
    console.error(
      "[steel] Install curl, then run: curl -sSf https://setup.steel.dev | sh"
    );
    // Don't fail npm install — just warn
    return;
  }

  // Run the cargo-dist installer
  try {
    execSync(`curl --proto '=https' --tlsv1.2 -LsSf ${INSTALLER_URL} | sh`, {
      stdio: "inherit",
      shell: "/bin/sh",
    });
    console.log("");
    console.log("[steel] Installation complete!");
    console.log(`[steel] Binary installed to ${BINARY_DIR}`);
    console.log(
      `[steel] Make sure ${BINARY_DIR} is in your PATH, then run: steel --help`
    );
  } catch (err) {
    console.error("");
    console.error("[steel] Automatic installation failed.");
    console.error("[steel] Install manually:");
    console.error("  curl -sSf https://setup.steel.dev | sh");
    console.error("");
    console.error(
      "[steel] Or download from: https://github.com/steel-dev/cli/releases"
    );
    // Don't fail npm install
  }
}

main();

use std::path::Path;

use crate::config::settings;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AuthSource {
    Env,
    Config,
    None,
}

impl std::fmt::Display for AuthSource {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Env => write!(f, "env (STEEL_API_KEY)"),
            Self::Config => write!(f, "config"),
            Self::None => write!(f, "none"),
        }
    }
}

#[derive(Debug, Clone)]
pub struct Auth {
    pub api_key: Option<String>,
    pub source: AuthSource,
}

/// Resolve API key with explicit inputs (testable).
///
/// Priority: env var → config file → none.
/// Matches TS `resolveBrowserAuth()` in `auth.ts`.
pub fn resolve_auth_with(env_api_key: Option<&str>, config_api_key: Option<&str>) -> Auth {
    // 1. STEEL_API_KEY env var
    if let Some(key) = env_api_key {
        let trimmed = key.trim();
        if !trimmed.is_empty() {
            return Auth {
                api_key: Some(trimmed.to_string()),
                source: AuthSource::Env,
            };
        }
    }

    // 2. config.json apiKey
    if let Some(key) = config_api_key {
        let trimmed = key.trim();
        if !trimmed.is_empty() {
            return Auth {
                api_key: Some(trimmed.to_string()),
                source: AuthSource::Config,
            };
        }
    }

    Auth {
        api_key: None,
        source: AuthSource::None,
    }
}

/// Read the API key from a config file at the given path.
pub fn read_api_key_from_config(path: &Path) -> Option<String> {
    settings::read_config_from(path)
        .ok()
        .and_then(|c| c.api_key)
        .filter(|k| !k.trim().is_empty())
}

/// Resolve API key from environment and default config path.
pub fn resolve_auth() -> Auth {
    let env_key = std::env::var("STEEL_API_KEY").ok();
    let config_key = read_api_key_from_config(&super::config_path());

    resolve_auth_with(env_key.as_deref(), config_key.as_deref())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn env_key_takes_priority() {
        let auth = resolve_auth_with(Some("env-key"), Some("config-key"));
        assert_eq!(auth.api_key.as_deref(), Some("env-key"));
        assert_eq!(auth.source, AuthSource::Env);
    }

    #[test]
    fn falls_back_to_config_key() {
        let auth = resolve_auth_with(None, Some("config-key"));
        assert_eq!(auth.api_key.as_deref(), Some("config-key"));
        assert_eq!(auth.source, AuthSource::Config);
    }

    #[test]
    fn no_key_returns_none() {
        let auth = resolve_auth_with(None, None);
        assert_eq!(auth.api_key, None);
        assert_eq!(auth.source, AuthSource::None);
    }

    #[test]
    fn empty_env_key_skipped() {
        let auth = resolve_auth_with(Some("  "), Some("config-key"));
        assert_eq!(auth.api_key.as_deref(), Some("config-key"));
        assert_eq!(auth.source, AuthSource::Config);
    }

    #[test]
    fn empty_config_key_skipped() {
        let auth = resolve_auth_with(None, Some("  "));
        assert_eq!(auth.api_key, None);
        assert_eq!(auth.source, AuthSource::None);
    }

    #[test]
    fn keys_are_trimmed() {
        let auth = resolve_auth_with(Some("  trimmed-key  "), None);
        assert_eq!(auth.api_key.as_deref(), Some("trimmed-key"));
    }

    #[test]
    fn read_api_key_from_config_file() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("config.json");
        std::fs::write(&path, r#"{"apiKey": "from-file"}"#).unwrap();

        assert_eq!(
            read_api_key_from_config(&path).as_deref(),
            Some("from-file")
        );
    }

    #[test]
    fn read_api_key_missing_file() {
        assert_eq!(
            read_api_key_from_config(Path::new("/nonexistent/config.json")),
            None
        );
    }

    #[test]
    fn read_api_key_empty_value() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("config.json");
        std::fs::write(&path, r#"{"apiKey": "  "}"#).unwrap();

        assert_eq!(read_api_key_from_config(&path), None);
    }
}

use std::io::Read;

use anyhow::{Context, Result, bail};
use clap::{Args, Parser, Subcommand};
use serde_json::Value;

use crate::api::client::SteelClient;
use crate::api::secrets::{CreateSecret, UpdateSecret};
use crate::util::{api, output};

#[derive(Subcommand)]
pub enum Command {
    /// List secrets
    List(ProjectArgs),

    /// Store a new secret
    Create(CreateArgs),

    /// Get one secret's metadata
    Get(IdArgs),

    /// Rename a secret or replace its value
    Update(UpdateArgs),

    /// Delete a secret
    Delete(IdArgs),
}

impl Command {
    pub const fn telemetry_name(&self) -> &'static str {
        match self {
            Self::List(_) => "list",
            Self::Create(_) => "create",
            Self::Get(_) => "get",
            Self::Update(_) => "update",
            Self::Delete(_) => "delete",
        }
    }
}

#[derive(Args)]
pub struct ProjectArgs {
    /// Project to use (defaults to the API key's project)
    #[arg(long = "project", value_name = "PROJECT_ID")]
    pub project_id: Option<String>,
}

#[derive(Parser)]
pub struct IdArgs {
    /// Secret ID
    pub secret_id: String,

    #[command(flatten)]
    pub project: ProjectArgs,
}

#[derive(Parser)]
pub struct CreateArgs {
    /// Secret name, also the environment variable name inside computers
    pub name: String,

    /// The secret value
    #[arg(long, value_name = "VALUE", conflicts_with = "value_stdin")]
    pub value: Option<String>,

    /// Read the secret value from stdin
    #[arg(long = "value-stdin")]
    pub value_stdin: bool,

    #[command(flatten)]
    pub project: ProjectArgs,
}

#[derive(Parser)]
pub struct UpdateArgs {
    /// Secret ID
    pub secret_id: String,

    /// New name
    #[arg(long)]
    pub name: Option<String>,

    /// New value
    #[arg(long, value_name = "VALUE", conflicts_with = "value_stdin")]
    pub value: Option<String>,

    /// Read the new value from stdin
    #[arg(long = "value-stdin")]
    pub value_stdin: bool,

    #[command(flatten)]
    pub project: ProjectArgs,
}

pub async fn run(command: Command) -> Result<()> {
    match command {
        Command::List(args) => run_list(args).await,
        Command::Create(args) => run_create(args).await,
        Command::Get(args) => run_get(args).await,
        Command::Update(args) => run_update(args).await,
        Command::Delete(args) => run_delete(args).await,
    }
}

pub fn trim_trailing_newline(text: &str) -> &str {
    let text = text.strip_suffix('\n').unwrap_or(text);
    text.strip_suffix('\r').unwrap_or(text)
}

pub fn read_value(value: Option<String>, from_stdin: bool) -> Result<Option<String>> {
    if from_stdin {
        let mut text = String::new();
        std::io::stdin()
            .read_to_string(&mut text)
            .context("Failed to read the value from stdin")?;
        let value = trim_trailing_newline(&text).to_string();
        if value.is_empty() {
            bail!("Nothing was read from stdin.");
        }
        return Ok(Some(value));
    }
    if value.as_deref() == Some("") {
        bail!("--value must not be empty.");
    }
    Ok(value)
}

pub fn name_of(secret: &Value) -> &str {
    secret["name"].as_str().unwrap_or("-")
}

pub fn id_of(secret: &Value) -> Result<String> {
    secret["id"]
        .as_str()
        .map(str::to_string)
        .context("the API returned a secret without an id")
}

async fn run_list(args: ProjectArgs) -> Result<()> {
    let (mode, base_url, auth) = api::resolve_with_auth();
    let client = SteelClient::new()?;
    let data = client
        .list_secrets(&base_url, mode, &auth, args.project_id.as_deref())
        .await?;
    if output::is_json() {
        output::success_data(data);
    } else {
        print_secrets(&data);
    }
    Ok(())
}

async fn run_create(args: CreateArgs) -> Result<()> {
    let Some(value) = read_value(args.value, args.value_stdin)? else {
        bail!("Give the value with --value or --value-stdin.");
    };
    let (mode, base_url, auth) = api::resolve_with_auth();
    let client = SteelClient::new()?;
    let request = CreateSecret {
        name: args.name,
        value,
        project_id: args.project.project_id,
    };
    let data = client
        .create_secret(&base_url, mode, &auth, &request)
        .await?;
    if output::is_json() {
        output::success_data(data);
    } else {
        println!("Created {} as {}.", name_of(&data), id_of(&data)?);
    }
    Ok(())
}

async fn run_get(args: IdArgs) -> Result<()> {
    let (mode, base_url, auth) = api::resolve_with_auth();
    let client = SteelClient::new()?;
    let data = client
        .get_secret(
            &base_url,
            mode,
            &auth,
            &args.secret_id,
            args.project.project_id.as_deref(),
        )
        .await?;
    output::success_data(data);
    Ok(())
}

async fn run_update(args: UpdateArgs) -> Result<()> {
    let request = UpdateSecret {
        name: args.name,
        value: read_value(args.value, args.value_stdin)?,
    };
    if request.is_empty() {
        bail!("Give something to change: --name, --value or --value-stdin.");
    }
    let (mode, base_url, auth) = api::resolve_with_auth();
    let client = SteelClient::new()?;
    let data = client
        .update_secret(
            &base_url,
            mode,
            &auth,
            &args.secret_id,
            args.project.project_id.as_deref(),
            &request,
        )
        .await?;
    if output::is_json() {
        output::success_data(data);
    } else {
        println!("Updated {}.", args.secret_id);
    }
    Ok(())
}

async fn run_delete(args: IdArgs) -> Result<()> {
    let (mode, base_url, auth) = api::resolve_with_auth();
    let client = SteelClient::new()?;
    let data = client
        .delete_secret(
            &base_url,
            mode,
            &auth,
            &args.secret_id,
            args.project.project_id.as_deref(),
        )
        .await?;
    if output::is_json() {
        output::success_data(data);
    } else {
        println!("Deleted {}.", args.secret_id);
    }
    Ok(())
}

fn print_secrets(data: &Value) {
    let secrets = data["secrets"].as_array().cloned().unwrap_or_default();
    if secrets.is_empty() {
        println!("No secrets.");
        return;
    }
    let rows: Vec<Vec<String>> = secrets
        .iter()
        .map(|secret| {
            vec![
                secret["id"].as_str().unwrap_or("").to_string(),
                name_of(secret).to_string(),
                secret["version"]
                    .as_u64()
                    .map_or_else(|| "-".to_string(), |version| version.to_string()),
                secret["updatedAt"].as_str().unwrap_or("").to_string(),
            ]
        })
        .collect();
    output::print_table(&["ID", "NAME", "VERSION", "UPDATED"], &rows);
}

#[cfg(test)]
mod tests {
